import { Injectable, computed, signal } from '@angular/core';
import { Subject } from 'rxjs';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';

export type SelectionPrimaryMode = 'QF' | 'F' | 'D';

export interface SelectionActionsState {
  qf: boolean;
  fact: boolean;
  doclink: boolean;
  exclusive: 'COPY' | null;
  qfIncludeNote: boolean;
  qfIncludeTextPlusNote: boolean;
  copyDocName: boolean;
  copyPagination: boolean;
}

export const SELECTION_ACTIONS_DEFAULT: SelectionActionsState = {
  qf: false,
  fact: true,
  doclink: true,
  exclusive: null,
  qfIncludeNote: false,
  qfIncludeTextPlusNote: false,
  copyDocName: false,
  copyPagination: false,
};

const STORAGE_KEY = 'selectionActions';
const STORAGE_KEY_QFSEL = 'selectionActions:qfactSelected';

@Injectable({ providedIn: 'root' })
export class SelectionActionsService {
  private readonly _state = signal<SelectionActionsState>(this.load());

  readonly state = this._state.asReadonly();

  readonly activeArr = computed<SelectionPrimaryMode[]>(() => {
    const s = this._state();
    const out: SelectionPrimaryMode[] = [];
    if (s.qf) out.push('QF');
    if (s.fact) out.push('F');
    if (s.doclink) out.push('D');
    return out;
  });

  readonly isCopy = computed(() => this._state().exclusive === 'COPY');
  readonly isSingle = computed(() => !this.isCopy() && this.activeArr().length === 1);
  readonly singleKind = computed<SelectionPrimaryMode | null>(() => this.isSingle() ? this.activeArr()[0] : null);
  readonly isQFactRapid = computed(() => this.isSingle() && this.singleKind() === 'QF');

  readonly modeLabel = computed<string | null>(() => {
    if (this.isCopy()) return 'Copy Mode';
    if (this.isSingle()) {
      const k = this.singleKind();
      return k === 'QF' ? 'QFact Mode' : k === 'F' ? 'Fact Mode' : 'DocLink Mode';
    }
    return null;
  });

  readonly summary = computed<string>(() => {
    if (this.isCopy()) {
      const parts = [this._state().copyDocName ? 'With Doc Name' : 'Text only'];
      if (this._state().copyPagination) parts.push('Page & Line');
      return parts.join(' + ');
    }
    if (this.isSingle()) return this.modeLabel()!;
    return this.activeArr().map(k => k === 'QF' ? 'QFact' : k === 'F' ? 'Fact' : 'DocLink').join(' • ');
  });

  /** Fired when an inline switcher (e.g. cursor button inside the selection
   *  popup) wants the toolbar's dropdown to open. The toolbar's
   *  SelectionActionsControl subscribes and calls openMenu() on its trigger
   *  so the dropdown anchors to the toolbar — not to the switcher. */
  private readonly _openToolbar$ = new Subject<void>();
  readonly openToolbar$ = this._openToolbar$.asObservable();

  requestOpenToolbar(): void {
    this._openToolbar$.next();
  }

  /** Issue IDs the user picked in the QFact panel for the next QFact capture.
   *  Empty array = "default" → the QFact panel renders Unassigned as the
   *  effective selection. Persisted to localStorage so PDF iframes
   *  (separate Angular instances) inherit the parent window's selection,
   *  and so swapping documents inside individual-doc keeps the picks
   *  intact — matching the product spec.
   *
   *  resetToDefaults() clears both this and the toolbar flags; call it
   *  when the user closes individual-doc or the tab unloads. */
  private readonly _qfactSelected = signal<string[]>(this.loadQFactSelected());
  readonly qfactSelected = this._qfactSelected.asReadonly();
  readonly qfactSelectedCount = computed(() => this._qfactSelected().length);

  toggleQFactIssue(nIid: string): void {
    this._qfactSelected.update(prev =>
      prev.includes(nIid) ? prev.filter(x => x !== nIid) : [...prev, nIid]
    );
    this.persistQFactSelected(this._qfactSelected());
  }

  /** Synchronously re-read qfactSelected from localStorage and reconcile the
   *  in-memory signal if they differ. Used by the QFact rapid-create path
   *  in iframe contexts (individual-doc) to bypass cross-window 'storage'
   *  event latency: when the parent updates qfactSelected, the iframe's
   *  signal updates only after the browser dispatches the 'storage' event,
   *  which can lag by tens of milliseconds. A fast highlight that mouse-ups
   *  inside that lag would otherwise read the stale signal and silently
   *  fall back to the Unassigned issue. Calling this at the start of submit
   *  guarantees the signal reflects the parent's latest write. */
  refreshQFactSelectedFromStorage(): string[] {
    const fromStorage = this.loadQFactSelected();
    const current = this._qfactSelected();
    const changed = fromStorage.length !== current.length
      || fromStorage.some((id, i) => id !== current[i]);
    if (changed) {
      this._qfactSelected.set(fromStorage);
    }
    return fromStorage;
  }

  setQFactIssues(nIids: string[]): void {
    this._qfactSelected.set([...nIids]);
    this.persistQFactSelected(this._qfactSelected());
  }

  clearQFactIssues(): void {
    this._qfactSelected.set([]);
    this.persistQFactSelected([]);
  }

  /** Reset to defaults: clears the explicit issue picks and restores the
   *  default toolbar mode (qf=false, fact=true, doclink=true). The host
   *  (individual-doc) calls this on ngOnDestroy / beforeunload so that
   *  re-opening a doc starts fresh — the QFact panel doesn't auto-open
   *  in evidence/admin pages just because the previous individual-doc
   *  session left QFact armed. */
  resetToDefaults(): void {
    this._qfactSelected.set([]);
    this.persistQFactSelected([]);
    this.commit(() => ({ ...SELECTION_ACTIONS_DEFAULT }));
  }

  /** Notifies subscribers that the per-user QFact prefs were just persisted
   *  to the backend (Manage Claims & Issues dialog closed with QFact-mode
   *  changes). The LEFT QFact panel listens and re-fetches its issue list so
   *  the new visibility / order takes effect without a full page refresh. */
  private readonly _qfactRefresh$ = new Subject<void>();
  readonly qfactRefresh$ = this._qfactRefresh$.asObservable();

  requestQFactRefresh(): void {
    this._qfactRefresh$.next();
  }

  /** Fired when the user clicks the "Manage" button on the QFact panel (or
   *  the QFact tab's gear icon). The host (pdf.component, transcript-viewer,
   *  individual-doc) subscribes and opens the existing `issue-manage` side
   *  panel with QFact mode pre-enabled — replacing the old standalone
   *  ManageIssuesDialogComponent popup. */
  private readonly _qfactManageRequest$ = new Subject<void>();
  readonly qfactManageRequest$ = this._qfactManageRequest$.asObservable();

  requestOpenQFactManage(): void {
    this._qfactManageRequest$.next();
  }

  constructor(private readonly storage: SecureStorageService) {
    // Cross-window sync: PDF documents in individual-doc render inside iframes
    // that bootstrap their own copies of this service, so the parent's QFact
    // toggle never reaches them on its own. The 'storage' event fires in every
    // OTHER same-origin window when localStorage changes (never in the writer)
    // — perfect for mirroring without a feedback loop.
    if (typeof window !== 'undefined') {
      window.addEventListener('storage', this.onCrossWindowStorage);
    }
  }

  private onCrossWindowStorage = (e: StorageEvent): void => {
    // null key fires on storage.clear(); refresh both signals.
    if (e.key === null) {
      this._state.set(this.load());
      this._qfactSelected.set(this.loadQFactSelected());
      return;
    }
    if (e.key === STORAGE_KEY) {
      this._state.set(this.load());
    } else if (e.key === STORAGE_KEY_QFSEL) {
      this._qfactSelected.set(this.loadQFactSelected());
    }
  };

  private commit(updater: (s: SelectionActionsState) => SelectionActionsState): void {
    this._state.update(updater);
    this.persist(this._state());
  }

  setQFact(): void {
    this.commit(s => ({ ...s, qf: true, fact: false, doclink: false, exclusive: null }));
  }

  setCopy(): void {
    this.commit(s => ({ ...s, qf: false, fact: false, doclink: false, exclusive: 'COPY' }));
  }

  toggleAdditive(key: 'fact' | 'doclink'): void {
    this.commit(prev => {
      if (prev.qf || prev.exclusive === 'COPY') {
        return { ...prev, qf: false, exclusive: null, fact: key === 'fact', doclink: key === 'doclink' };
      }
      const next = { ...prev, [key]: !prev[key] };
      if (!next.fact && !next.doclink) next[key] = true;
      return next;
    });
  }

  setQfSubOption(key: 'qfIncludeNote' | 'qfIncludeTextPlusNote', value: boolean): void {
    this.commit(s => ({ ...s, [key]: value }));
  }

  setCopySubOption(key: 'copyDocName' | 'copyPagination', value: boolean): void {
    this.commit(s => ({ ...s, [key]: value }));
  }

  private load(): SelectionActionsState {
    try {
      const raw = this.storage?.getStorage(STORAGE_KEY);
      if (typeof raw === 'string') {
        try {
          const parsed = JSON.parse(raw);
          if (parsed && typeof parsed === 'object') {
            return { ...SELECTION_ACTIONS_DEFAULT, ...parsed };
          }
        } catch {
          // legacy "[object Object]" strings from the pre-stringify persist;
          // treated as missing so we fall back to defaults.
        }
      }
      return { ...SELECTION_ACTIONS_DEFAULT };
    } catch {
      return { ...SELECTION_ACTIONS_DEFAULT };
    }
  }

  private persist(state: SelectionActionsState): void {
    try {
      // setStorage writes through localStorage.setItem, which coerces non-string
      // values to "[object Object]". Stringify so load() round-trips and the
      // 'storage' event delivers a parseable newValue to other windows.
      this.storage.setStorage(STORAGE_KEY, JSON.stringify(state));
    } catch {
      // storage failures are non-fatal — state still lives in memory
    }
  }

  /** Stringified array of issue IDs the user has picked. Stored under a
   *  separate key so cross-window sync only fires when picks actually
   *  change (the toolbar mode toggles update much more often). */
  private loadQFactSelected(): string[] {
    try {
      const raw = this.storage?.getStorage(STORAGE_KEY_QFSEL);
      if (typeof raw === 'string') {
        try {
          const parsed = JSON.parse(raw);
          if (Array.isArray(parsed)) return parsed.filter(x => typeof x === 'string');
        } catch {
          // fall through to default
        }
      }
      return [];
    } catch {
      return [];
    }
  }

  private persistQFactSelected(ids: string[]): void {
    try {
      this.storage.setStorage(STORAGE_KEY_QFSEL, JSON.stringify(ids));
    } catch {
      // non-fatal; signal still has the value
    }
  }
}
